<script lang="ts">import { getPlatform } from '../platform';let { code = '', lang = '' }: { code?: string; lang?: string } = $props();async function copy() { await getPlatform().copyText(code); }</script><div class="code"><div class="head"><span>{lang}</span><button onclick={copy}>Copy</button></div><pre>{code}</pre></div><style>.code{background:var(--bg-1);border:1px solid var(--border);border-radius:var(--radius);overflow:hidden}.head{display:flex;justify-content:space-between;padding:var(--space-2) var(--space-3);color:var(--text-2);font-size:var(--fs-xs)}.head button{background:transparent;border:none;color:var(--accent)}pre{margin:0;padding:var(--space-4);overflow:auto;font-family:var(--font-mono);font-size:var(--fs-sm)}</style>
